export function initialize(sentinelElement, dotNetRef) {
    const observer = new IntersectionObserver(entries => {
        for (const entry of entries) {
            if (entry.isIntersecting) {
                dotNetRef.invokeMethodAsync('OnSentinelVisible');
            }
        }
    }, { rootMargin: '0px 0px 128px 0px' });

    observer.observe(sentinelElement);

    return { observer, sentinelElement };
}

export function dispose(instance) {
    if (instance?.observer) {
        instance.observer.unobserve(instance.sentinelElement);
        instance.observer.disconnect();
    }
}

@typeparam TItem
@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="infinite-scroll-container" style="overflow-y:auto;">
    @foreach (var item in Items)
    {
        @ChildContent(item)
    }

    @if (HasMore)
    {
        <div @ref="_sentinelRef" class="infinite-scroll-sentinel">
            @if (_isLoading)
            {
                <div class="d-flex justify-content-center py-3">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public IReadOnlyList<TItem> Items { get; set; } = [];

    [Parameter, EditorRequired]
    public bool HasMore { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnLoadMore { get; set; }

    [Parameter, EditorRequired]
    public RenderFragment<TItem> ChildContent { get; set; } = default!;

    private ElementReference _sentinelRef;
    private IJSObjectReference? _module;
    private IJSObjectReference? _observerInstance;
    private DotNetObjectReference<InfiniteScrollList<TItem>>? _dotNetRef;
    private bool _isLoading;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./js/infinite-scroll.js");
            await StartObserver();
        }
    }

    public override async Task SetParametersAsync(ParameterView parameters)
    {
        var previousHasMore = HasMore;
        await base.SetParametersAsync(parameters);

        // Re-attach observer when HasMore transitions back to true
        if (!previousHasMore && HasMore && _module is not null)
        {
            await StartObserver();
        }
    }

    private async Task StartObserver()
    {
        if (_observerInstance is not null)
        {
            await _module!.InvokeVoidAsync("dispose", _observerInstance);
            _observerInstance = null;
        }

        // Wait one render cycle so the sentinel element is in the DOM
        await Task.Yield();
        StateHasChanged();
        await Task.Yield();

        _observerInstance = await _module!.InvokeAsync<IJSObjectReference>(
            "initialize", _sentinelRef, _dotNetRef);
    }

    [JSInvokable]
    public async Task OnSentinelVisible()
    {
        if (_isLoading || !HasMore)
            return;

        _isLoading = true;
        StateHasChanged();

        await OnLoadMore.InvokeAsync();

        _isLoading = false;
        StateHasChanged();
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            if (_observerInstance is not null)
            {
                await _module.InvokeVoidAsync("dispose", _observerInstance);
            }
            await _module.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

